// #80e710 במובייל (390px) התפריט הראשי — все пункты доступны через кнопку «תפריט ראשי», меню аккаунта на аватаре
// «חשבון», нет горизонтальной прокрутки; граница режима 900 (свёрнуто) / 901 (боковое меню).
// Кейсы: .qa/tests/navigation/NAV-01..NAV-04. План: specs/navigation.md.
// Только просмотр: ADMIN (компания A) и USER (QA Member 2) — ничего не нажимаем, кроме меню и перехода по пункту.
// «התנתק» не нажимается.
import { test, expect, Page, Locator } from '@playwright/test';
import { authState } from '../helpers/tenderflow';

const WIDTHS = [390, 375];
const ADMIN_ITEMS = ['פיד מכרזים', 'המכרזים שלי', 'החברה', 'פרופיל חברה', 'מאגר מסמכים', 'צוות והרשאות', 'הגדרות'];
const USER_ITEMS = ['פיד מכרזים', 'המכרזים שלי'];
const ADMIN_ONLY = ['החברה', 'פרופיל חברה', 'צוות והרשאות'];

const menuButton = (page: Page) => page.getByRole('button', { name: 'תפריט ראשי' });
const mainNav = (page: Page) => page.getByRole('navigation', { name: 'ניווט ראשי' });
const navItem = (page: Page, text: string) => mainNav(page).getByText(text, { exact: true });
const avatar = (page: Page) => page.getByRole('button', { name: 'חשבון' });

/** Элемент целиком в пределах ширины окна (ничего не уходит за левый/правый край). */
async function expectInViewport(page: Page, loc: Locator, what: string) {
  await expect(loc, what).toBeVisible();
  const box = await loc.boundingBox();
  const vw = page.viewportSize()!.width;
  expect(box, what).toBeTruthy();
  expect(box!.x, `${what}: левый край`).toBeGreaterThanOrEqual(-0.5);
  expect(box!.x + box!.width, `${what}: правый край`).toBeLessThanOrEqual(vw + 0.5);
}

/** Нет горизонтальной прокрутки страницы: scrollWidth == innerWidth. */
async function expectNoHorizontalScroll(page: Page, what: string) {
  await expect
    .poll(() => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth), { message: `${what}: scrollWidth > innerWidth` })
    .toBeLessThanOrEqual(0);
}

async function openFeed(page: Page, width: number) {
  await page.setViewportSize({ width, height: 812 });
  await page.goto('/');
  await expect(page.getByRole('heading', { name: 'פיד מכרזים', level: 1 })).toBeVisible();
}

test.describe('תפריט ראשי במובייל — מנהל חשבון', () => {
  test.use({ storageState: authState('admin') });

  for (const w of WIDTHS) {
    test(`${w}px: "תפריט ראשי" פותח את כל הפריטים כולל "החברה", בחירת פריט סוגרת ועוברת #80e710 @mobile @prod-safe`, async ({ page }) => {
      // NAV-01
      await openFeed(page, w);
      await expectInViewport(page, menuButton(page), 'кнопка «תפריט ראשי»');
      await expectInViewport(page, avatar(page), 'аватар «חשבון»');
      await expect(navItem(page, 'צוות והרשאות'), 'до нажатия меню свёрнуто').toBeHidden();

      await menuButton(page).click();
      for (const item of ADMIN_ITEMS) await expectInViewport(page, navItem(page, item), `пункт «${item}»`);
      await expectNoHorizontalScroll(page, `${w}px, меню открыто`);

      await mainNav(page).getByRole('link', { name: 'צוות והרשאות', exact: true }).click();
      await page.waitForURL((u) => u.pathname === '/users');
      await expect(page.getByRole('heading', { name: 'משתמשי החברה', level: 1 })).toBeVisible();
      await expect(navItem(page, 'צוות והרשאות'), 'после выбора пункта меню закрыто').toBeHidden();
    });

    test(`${w}px: אוואטר "חשבון" פותח תפריט חשבון עם "התנתק" בתוך המסך #80e710 @mobile @prod-safe`, async ({ page }) => {
      // NAV-01 (меню аккаунта)
      await openFeed(page, w);
      await avatar(page).click();
      await expectInViewport(page, page.getByText('התנתק', { exact: true }), '«התנתק»');
    });

    test(`${w}px: אין גלילה אופקית ב-/, /onboarding, /users #80e710 @mobile @prod-safe`, async ({ page }) => {
      // NAV-03
      await page.setViewportSize({ width: w, height: 812 });
      for (const path of ['/', '/onboarding', '/users']) {
        await page.goto(path);
        await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();
        if (path === '/users') await expect(page.getByRole('main').getByRole('row').nth(1)).toBeVisible();
        await expectInViewport(page, avatar(page), `${path}: аватар «חשבון»`);
        await expectNoHorizontalScroll(page, `${w}px ${path}`);
      }
    });
  }
});

test.describe('תפריט ראשי במובייל — משתמש רגיל', () => {
  test.use({ storageState: authState('user') });

  for (const w of WIDTHS) {
    test(`${w}px: משתמש רגיל רואה בתפריט רק "פיד מכרזים" ו"המכרזים שלי", בלי "החברה" #80e710 @mobile @prod-safe`, async ({ page }) => {
      // NAV-02
      await openFeed(page, w);
      await menuButton(page).click();
      for (const item of USER_ITEMS) await expectInViewport(page, navItem(page, item), `пункт «${item}»`);
      for (const item of ADMIN_ONLY) await expect(navItem(page, item), `у USER нет «${item}»`).toHaveCount(0);
      await expectNoHorizontalScroll(page, `${w}px USER, меню открыто`);

      // Меню аккаунта — на чистой странице (закрытие меню Escape/тапом вне — находки 14.11, здесь не проверяются).
      await openFeed(page, w);
      await avatar(page).click();
      await expectInViewport(page, page.getByText('התנתק', { exact: true }), '«התנתק»');
    });
  }
});

test.describe('גבול 900/901 — מנהל חשבון', () => {
  test.use({ storageState: authState('admin') });

  test('900px — תפריט מקופל מאחורי "תפריט ראשי"; 901px — תפריט צד גלוי בלי כפתור #80e710 @desktop @prod-safe', async ({ page }) => {
    // NAV-04: комментарий программиста 12.11 «עד 900px».
    await page.setViewportSize({ width: 900, height: 900 });
    await page.goto('/');
    await expect(page.getByRole('heading', { name: 'פיד מכרזים', level: 1 })).toBeVisible();
    await expect(menuButton(page)).toBeVisible();
    await expect(navItem(page, 'צוות והרשאות')).toBeHidden();
    await expectNoHorizontalScroll(page, '900px');

    await page.setViewportSize({ width: 901, height: 900 });
    await expect(menuButton(page)).toBeHidden();
    await expectInViewport(page, navItem(page, 'צוות והרשאות'), '901px: пункт «צוות והרשאות»');
    await expectInViewport(page, avatar(page), '901px: аватар «חשבון»');
    await expectNoHorizontalScroll(page, '901px');
  });
});
